check('Continue Hall restores progress without clearing Scene Memories', `(() => {const oldHall=localStorage.getItem(HALL_SAVE_KEY), oldScenes=localStorage.getItem(HALL_SCENE_HISTORY_KEY), oldAssets=runtimeAssetsReady; try {mode='walk';state.gameMode='hallBattles';state.map='emberHallBattles';state.party=['Verseborn','Mira'];state.activeParty=['Verseborn','Mira'];state.hallBattles={unlockedStage:12,clearedStages:[1,2,3],recruitStages:[3],pendingRecruit:0};localStorage.setItem(HALL_SCENE_HISTORY_KEY,'scene-history');saveGame(HALL_SAVE_KEY);state.party=['Verseborn'];state.hallBattles={unlockedStage:1,clearedStages:[],recruitStages:[],pendingRecruit:0};runtimeAssetsReady=true;startHallBattles(true);return state.party.includes('Mira')&&state.hallBattles.unlockedStage===12&&localStorage.getItem(HALL_SCENE_HISTORY_KEY)==='scene-history';} finally {runtimeAssetsReady=oldAssets;[[HALL_SAVE_KEY,oldHall],[HALL_SCENE_HISTORY_KEY,oldScenes]].forEach(([key,value])=>value===null?localStorage.removeItem(key):localStorage.setItem(key,value));}})()`);
check('Hall hub uses its own art with Marla, Glimmer and the Trial Gate', `(() => {const hub=maps.emberHallBattles; return hub.background==='ember-hall-battle'&&hub.collision==='lantern'&&hub.exits.length===0&&['Marla','Glimmer','Stage'].every(id=>hub.points.some(point=>point.id===id));})()`);
