check('Hall enemies use the selected stage level and normal XP formula', `(() => {const units=hallEnemiesForStage(40).map(unit=>prepareEnemyForBattle(unit)); return units.length===3&&units.every(unit=>unit.level===40&&unit.xp===14+40*7);})()`);
check('Cleared Hall stages render as replayable while future stages stay locked', `(() => {state.gameMode='hallBattles'; state.hallBattles={unlockedStage:2,clearedStages:[1],recruitStages:[],pendingRecruit:0}; renderHallBattleMap(); const html=el.menuBody.innerHTML; return (html.match(/data-hall-stage=/g)||[]).length===40&&html.includes('STAGE 01')&&html.includes('CLEARED / REPLAY')&&html.includes('STAGE 03')&&html.includes('is-locked');})()`);
check('Only a first Hall clear unlocks progress and schedules recruitment', `(() => {state.party=['Verseborn']; state.echoForgeRank=0; state.hallBattles={unlockedStage:3,clearedStages:[1,2],recruitStages:[],pendingRecruit:0}; const first=recordHallBattleClear(3), replay=recordHallBattleClear(3); return first&&!replay&&state.hallBattles.unlockedStage===4&&state.hallBattles.pendingRecruit===3&&state.echoForgeRank===3&&state.hallBattles.clearedStages.join(',')==='1,2,3';})()`);
check('Hall recruitment offers every existing companion at three-stage intervals', `HALL_RECRUIT_INTERVAL===3&&HALL_RECRUITS.length===6&&HALL_RECRUITS.every(id=>baseJobs[id]&&id!=='Verseborn')`);
check('Glimmer sells two repeatable Echo Hunt items per rank through forty', `(() => {state.echoForgeRank=40; state.endgameRank=0; const wares=vendorWares('workshop').filter(ware=>ware.kind==='gear'&&echoForgeGearNames.has(ware.name)); return echoForgeGear.length===80&&wares.length===80&&new Set(wares.map(ware=>ware.name)).size===80&&Array.from({length:40},(_,index)=>wares.filter(ware=>gearByName(ware.name).echoRank===index+1).length===2).every(Boolean);})()`);
check('Hall stages 1-20 grant new random equipment from Uncommon through Legendary', `(() => {const oldRandom=Math.random, oldOwned=[...state.ownedGear], oldCopies={...state.gearCopies}, oldRarities={...state.gearRarities}, oldAffixes=structuredClone(state.gearAffixes), oldInstances=structuredClone(state.gearInstances), oldNext=state.nextGearInstance; try {const rolled=[0,.26,.51,.76].map(value=>(Math.random=()=>value,rollHallGearRarity())); Math.random=()=>0; const rewards={drops:[],gearDrops:[]}; const awarded=guaranteeHallBattleGearReward(rewards,20); return rolled.join(',')==='Uncommon,Rare,Epic,Legendary'&&rewards.gearDrops.length===1&&rewards.drops.length===1&&rewards.drops[0].kind==='gear'&&HALL_STANDARD_GEAR_POOL.some(gear=>gear.name===awarded.name)&&HALL_GEAR_RARITIES.includes(awarded.rarity);} finally {Math.random=oldRandom; state.ownedGear=oldOwned; state.gearCopies=oldCopies; state.gearRarities=oldRarities; state.gearAffixes=oldAffixes; state.gearInstances=oldInstances; state.nextGearInstance=oldNext; gearInstances=state.gearInstances;}})()`);
check('Hall stages 21-40 always grant a new Legendary with four affixes', `(() => {const oldRandom=Math.random, oldOwned=[...state.ownedGear], oldCopies={...state.gearCopies}, oldRarities={...state.gearRarities}, oldAffixes=structuredClone(state.gearAffixes), oldInstances=structuredClone(state.gearInstances), oldNext=state.nextGearInstance; let roll=0; try {state.ownedGear=state.ownedGear.filter(name=>!HALL_LEGENDARY_GEAR_POOL.some(gear=>gear.name===name)); HALL_LEGENDARY_GEAR_POOL.forEach(gear=>state.gearCopies[gear.name]=0); Math.random=()=>((roll++*.173)%1); const rewards={drops:[],gearDrops:[]}; const awarded=guaranteeHallBattleGearReward(rewards,21); return awarded.rarity==='Legendary'&&HALL_LEGENDARY_GEAR_POOL.some(gear=>gear.name===awarded.name)&&gearAffixes(awarded.ref).length===4&&rewards.gearDrops.length===1;} finally {Math.random=oldRandom; state.ownedGear=oldOwned; state.gearCopies=oldCopies; state.gearRarities=oldRarities; state.gearAffixes=oldAffixes; state.gearInstances=oldInstances; state.nextGearInstance=oldNext; gearInstances=state.gearInstances;}})()`);
check('Seven deep Hall milestones distribute one unique ultimate weapon per hero', `HALL_ULTIMATE_REWARD_STAGES.size===7&&HALL_ULTIMATE_WEAPONS.length===7&&new Set(HALL_ULTIMATE_WEAPONS.flatMap(gear=>gearOwners[gear.name]||[])).size===7&&HALL_ULTIMATE_WEAPONS.every(gear=>weaponBasicAttackEffect(gear)&&gearEffects(gear).length)`);
check('Deep Hall ultimate milestones prioritize missing hero weapons on clears and replays', `(() => {const oldOwned=[...state.ownedGear], oldCopies={...state.gearCopies}; try {HALL_ULTIMATE_WEAPONS.forEach(gear=>{state.ownedGear=state.ownedGear.filter(name=>name!==gear.name);state.gearCopies[gear.name]=0;}); const candidates=hallGearRewardCandidates(21); return candidates.length===7&&candidates.every(gear=>HALL_ULTIMATE_WEAPONS.includes(gear));} finally {state.ownedGear=oldOwned;state.gearCopies=oldCopies;}})()`);
check('All party XP sources award exactly twice their listed amount', `(() => {const oldParty=[...state.party], oldActive=[...state.activeParty], oldProgress=structuredClone(state.heroProgress); try {state.party=['Verseborn','Mira'];state.activeParty=['Verseborn'];state.heroProgress.Verseborn={level:1,xp:0,talents:[],pendingMilestones:[]};state.heroProgress.Mira={level:1,xp:0,talents:[],pendingMilestones:[]};const summary=awardPartyXp(20,'test');return XP_MULTIPLIER===2&&state.heroProgress.Verseborn.xp===40&&state.heroProgress.Mira.xp===26&&summary.startsWith('40 XP');} finally {state.party=oldParty;state.activeParty=oldActive;state.heroProgress=oldProgress;}})()`);
check('Glimmer and Kael transformation Ultimates unlock at level ten', `(() => {const forms={Glimmer:'mech',Kael:'shadowpriest'}, oldLevels=Object.fromEntries(Object.keys(forms).map(id=>[id,progressFor(id).level])); try {return TRANSFORMATION_UNLOCK_LEVEL===10&&Object.entries(forms).every(([id,form])=>{progressFor(id).level=9;const locked=!battleSkills(id,{id}).some(skillEntry=>skillEntry.transform===form);progressFor(id).level=10;const unlocked=battleSkills(id,{id}).filter(skillEntry=>skillEntry.transform===form);return locked&&unlocked.length===1&&unlocked[0].anim==='ultimate';});} finally {Object.entries(oldLevels).forEach(([id,level])=>progressFor(id).level=level);}})()`);
check('Repeated Hall equipment drops remain separate copies with independent rarity and affixes', `(() => {const name='Ashrunner Knife', oldOwned=[...state.ownedGear], oldCopies={...state.gearCopies}, oldRarities={...state.gearRarities}, oldAffixes=structuredClone(state.gearAffixes), oldInstances=structuredClone(state.gearInstances), oldNext=state.nextGearInstance; try {state.ownedGear=state.ownedGear.filter(entry=>entry!==name); state.gearCopies[name]=0; delete state.gearRarities[name]; delete state.gearAffixes[name]; Object.keys(gearInstances).filter(ref=>gearInstance(ref)?.name===name).forEach(ref=>delete gearInstances[ref]); const a=addOwnedGear(name,1,{rarity:'Uncommon',rollAffixes:true,separateCopy:true})[0], b=addOwnedGear(name,1,{rarity:'Legendary',rollAffixes:true,separateCopy:true})[0]; return a!==b&&gearRarity(a)==='Uncommon'&&gearRarity(b)==='Legendary'&&gearAffixes(a).length===1&&gearAffixes(b).length===4&&ownedGearRefs('weapon','Verseborn').includes(a)&&ownedGearRefs('weapon','Verseborn').includes(b);} finally {state.ownedGear=oldOwned; state.gearCopies=oldCopies; state.gearRarities=oldRarities; state.gearAffixes=oldAffixes; state.gearInstances=oldInstances; state.nextGearInstance=oldNext; gearInstances=state.gearInstances;}})()`);
check('Hall battle endings fully restore HP and MP before returning to the Hall', `(() => {state.party=['Verseborn','Mira']; baseJobs.Verseborn.hp=1; baseJobs.Verseborn.mp=0; baseJobs.Mira.hp=2; baseJobs.Mira.mp=1; returnToHallAfterBattle(); return state.map==='emberHallBattles'&&state.party.every(id=>baseJobs[id].hp===totals(id).max&&baseJobs[id].mp===totals(id).mp);})()`);
check('Ten new battle arenas are registered and available as compact WebP assets', `(() => {const ids=['cinder-terrace','lantern-tavern','reverie-garden','reverie-library','guildspire-marble','cinder-sunset','fallen-dawn','cinder-ruins','cinder-cataclysm','lantern-stage']; return ids.every(id=>battleImageFiles[id]?.endsWith('.webp'));})()`);
check('Battle arenas follow locations and give special Hall encounters their own stage', `(() => {const oldMap=state.map, oldBattle=battle; try {battle=null; const expected={lantern:'lantern-stage',ashLane:'cinder-terrace',ashDock:'cinder-sunset',reverieCourt:'reverie-garden',reverieArchive:'reverie-library',guildHall:'guildspire-marble',emberArmory:'cinder-ruins',dawnCauseway:'fallen-dawn'}; const mapped=Object.entries(expected).every(([mapId,arena])=>(state.map=mapId,battleArenaFor(maps[mapId])===arena)); const hallArenas=new Set(HALL_BATTLE_BLUEPRINTS.map(info=>(battle={hallStage:info.stage},state.map=info.mapId,battleArenaFor(maps[info.mapId])))); battle={hallStage:40}; state.map='alarm'; return mapped&&hallArenas.size>=10&&battleArenaFor(maps.alarm)==='cinder-cataclysm';} finally {state.map=oldMap; battle=oldBattle;}})()`);
check('Every Hall recruit has one welcome, humorous and warm scene with compact dialogue', `(() => {const history={seen:[],lastByRecruit:{}}; return HALL_RECRUITS.every(recruit=>{const scenes=RECRUIT_SCENES.filter(scene=>scene.recruit===recruit); return scenes.length===3&&['welcome','humorous','warm'].every(variant=>scenes.filter(scene=>scene.variant===variant).length===1)&&scenes.every(scene=>{const partner=scene.preferred[0]||'Verseborn'; const actors=scene.cast||[partner,recruit]; const lines=scene.build({recruit,partner,history,actors}); return lines.length>=4&&lines.length<=7&&lines.filter(line=>line[2]).length<=4;});});})()`);
check('Recruit scene IDs stay unique and existing welcome references stay unchanged', `(() => {const ids=RECRUIT_SCENES.map(scene=>scene.id); const expected={Mira:['mira-welcome','Spare Blades','training-room'],Seerin:['seerin-welcome','Practice Blades','training-room'],Kael:['kael-welcome','A Quiet Shelf','kael-library'],Torren:['torren-welcome','Sit Down','torren-kitchen'],Sparky:['sparky-welcome','A Shiny Welcome','sparky-coop'],Glimmer:['glimmer-welcome','Bench Rights','glimmer-lab']}; return new Set(ids).size===ids.length&&Object.entries(expected).every(([recruit,[id,title,room]])=>{const scene=RECRUIT_SCENES.find(entry=>entry.recruit===recruit&&entry.variant==='welcome');return scene?.id===id&&scene.title===title&&scene.room===room;});})()`);
check('Recruit scenes use eight supplied room images plus the existing Trial Room map', `Object.keys(recruitSceneImageFiles).length===8&&Object.values(recruitSceneImageFiles).every(file=>file.endsWith('.webp'))&&Object.keys(RECRUIT_SCENE_ROOM_NAMES).every(id=>id==='trial-room'||recruitSceneImageFiles[id])&&RECRUIT_SCENES.find(scene=>scene.id===EMBER_HALL_INTRO_ID)?.room==='trial-room'&&maps.emberHallBattles.background==='ember-hall-battle'`);
check('Updated welcome scenes contain the requested full-roster dialogue', `(() => {const expected={'mira-welcome':['You carry too many knives.','And still not enough.','At last, a woman of refined priorities.','If you\\'re staying, you train properly.','Then try to keep up.'],'seerin-welcome':['You entered like a knight from a story.','I prefer prepared.','That still sounds dramatic.','Good. Then let\\'s test your footing.','Now this feels like home.'],'kael-welcome':['Before anything else, there are hall rules.','A thrilling opening.','Do unstable devices have a shelf?','No.','He truly is the spine of this place.'],'torren-welcome':['Good. Sit down.','An excellent first command.','Stew first. Questions later.','Prrrp!','No, you can\\'t have the whole pot.'],'sparky-welcome':['Behold: the smallest legend in the hall.','Prrr!','...That is unfairly cute.','He\\'s adorable.','Excellent. He has defeated you both.'],'glimmer-welcome':['Good news. I improved it.','Why is it smoking?','Because progress is happening.','I admire the confidence. I fear the result.','Both are correct.']}; const actors=['Verseborn',...HALL_RECRUITS]; const history={seen:[],lastByRecruit:{}}; return Object.entries(expected).every(([id,text])=>RECRUIT_SCENES.find(scene=>scene.id===id).build({partner:'Verseborn',history,actors}).map(line=>line[1]).join('|')===text.join('|'));})()`);
check('The first Hall arrival keeps its exact compact introduction and single effect', `(() => {const scene=RECRUIT_SCENES.find(entry=>entry.id===EMBER_HALL_INTRO_ID),lines=scene.build({});return scene.title==='Welcome to Ember Hall'&&lines.map(line=>line[1]).join('|')==="So. This is Ember Hall.|I expected more banners. Possibly a choir.|Give me twenty minutes.|You fight the trials. You come back here. You get stronger.|And ideally remain mostly alive.|That too.|When you're ready, step into the trial."&&lines.filter(line=>line[2]?.effect).length===1;})()`);
check('Welcome scenes give each staged character at most one primary action and one scene effect', `RECRUIT_SCENES.filter(scene=>scene.variant==='welcome').every(scene=>{const lines=scene.build({partner:'Verseborn',history:{seen:[],lastByRecruit:{}},actors:scene.cast||[]});const actors=lines.map(line=>line[2]?.actor).filter(Boolean);return new Set(actors).size===actors.length&&lines.filter(line=>line[2]?.effect).length<=1;})`);
check('Welcome actions use short scene-specific motions without spins or generic emotes', `(() => {const expected=['welcome-step','entrance','tool-tap','practice-strike','spar-dodge','flourish','dagger-flip','shelf-place','shelf-straighten','stir','small-step','hop-to-pot','fly-oval','approach-lean','reach','tinker-recoil','recoil'];const actions=RECRUIT_SCENES.filter(scene=>scene.variant==='welcome').flatMap(scene=>[scene.cast||[],['Verseborn',scene.recruit]].flatMap(actors=>scene.build({partner:'Verseborn',history:{seen:[],lastByRecruit:{}},actors}).flatMap(line=>line[2]?[line[2],...(line[2].with||[])]:[])));return expected.every(motion=>actions.some(action=>action.motion===motion))&&actions.every(action=>!['spin','circle','hop'].includes(action.motion)&&!action.emote&&action.duration>=60&&action.duration<=180);})()`);
check('Mira and Seerin share a controlled practice exchange', `(() => {const lines=RECRUIT_SCENES.find(scene=>scene.id==='mira-welcome').build({actors:['Verseborn','Seerin','Mira'],history:{seen:[],lastByRecruit:{}}});const spar=lines.map(line=>line[2]).find(action=>action?.motion==='practice-strike');return spar?.with?.length===1&&spar.with[0].actor==='Mira'&&spar.with[0].motion==='spar-dodge';})()`);
check('Scene motion profiles move, pose and settle back to idle', `(() => {const strike={facing:3,anim:'melee',motion:'practice-strike',actionDx:0},dodge={facing:1,anim:'melee',motion:'spar-dodge',actionDx:0},stir={facing:1,anim:'melee',motion:'stir',actionDx:0},recoil={facing:3,anim:'walk',motion:'recoil',actionDx:0};const strikeHit=recruitScenePoseAt(strike,.4),strikeDone=recruitScenePoseAt(strike,1),dodgeHit=recruitScenePoseAt(dodge,.5),stirA=recruitScenePoseAt(stir,.12),stirB=recruitScenePoseAt(stir,.2),recoilHit=recruitScenePoseAt(recoil,.5),done=recruitScenePoseAt(recoil,1,false);return strikeHit.x>0&&strikeHit.anim==='melee'&&Math.abs(strikeDone.x)<.01&&dodgeHit.x>0&&stirA.x!==stirB.x&&recoilHit.x<0&&done.x===0&&done.y===0&&done.anim==='idle';})()`);
check('Sparky follows an airborne oval and finishes hovering at his start point', `(() => {const sparky={facing:1,anim:'walk',motion:'fly-oval',actionDx:0};const start=recruitScenePoseAt(sparky,0),up=recruitScenePoseAt(sparky,.25),right=recruitScenePoseAt(sparky,.5),down=recruitScenePoseAt(sparky,.75),finish=recruitScenePoseAt(sparky,1);return up.y<start.y&&right.x>up.x&&down.y>right.y&&finish.x<down.x&&Math.abs(finish.x-start.x)<.01&&finish.y<0&&finish.anim==='walk';})()`);
check('First recruitment welcomes once, then rotates later variants without repeats', `(() => {const welcome=selectRecruitScene('Mira',{seen:[],lastByRecruit:{}}); const funny=selectRecruitScene('Mira',{seen:['mira-welcome'],lastByRecruit:{Mira:'mira-welcome'}}); const warm=selectRecruitScene('Mira',{seen:['mira-welcome','mira-humorous'],lastByRecruit:{Mira:'mira-humorous'}}); const rotated=selectRecruitScene('Mira',{seen:['mira-welcome','mira-humorous','mira-warm'],lastByRecruit:{Mira:'mira-warm'}}); return welcome.variant==='welcome'&&funny.variant==='humorous'&&warm.variant==='warm'&&rotated.variant==='humorous';})()`);
check('Scene partners and staged actors are limited to the current run roster', `(() => {state.party=['Verseborn','Mira']; const scene=RECRUIT_SCENES.find(entry=>entry.id==='mira-humorous'); const partner=recruitScenePartner(scene); const actors=recruitSceneActors(scene,partner); return partner==='Verseborn'&&actors.length===2&&actors.every(actor=>state.party.includes(actor.id))&&!actors.some(actor=>actor.id==='Glimmer');})()`);
check('Recruit scene playback uses portraits, short actions and a visible skip state', `(() => {localStorage.removeItem(HALL_SCENE_HISTORY_KEY); state.gameMode='hallBattles'; state.party=['Verseborn','Mira']; state.activeParty=['Verseborn','Mira']; const scene=RECRUIT_SCENES.find(entry=>entry.id==='mira-welcome'); const started=playRecruitScene(scene); const history=loadRecruitSceneHistory(); const valid=started&&mode==='talk'&&talkSkippable&&talkPortraits.join(',')==='Verseborn,Mira'&&history.seen.includes(scene.id)&&scene.build({partner:'Verseborn',history,actors:['Verseborn','Mira']}).some(line=>line[2]?.anim); skipTalk(); return valid&&mode==='walk'&&!activeRecruitScene&&!talkSkippable;})()`);
check('Skipping a recruitment scene does not change resources or Hall progress', `(() => {localStorage.removeItem(HALL_SCENE_HISTORY_KEY); state.gameMode='hallBattles'; state.party=['Verseborn','Kael']; state.activeParty=['Verseborn','Kael']; state.gold=321; state.resonance=17; state.hallBattles={unlockedStage:8,clearedStages:[1,2,3],recruitStages:[3],pendingRecruit:0}; const before=JSON.stringify({gold:state.gold,resonance:state.resonance,hall:state.hallBattles}); playRecruitScene(RECRUIT_SCENES.find(scene=>scene.id==='kael-welcome')); skipTalk(); return before===JSON.stringify({gold:state.gold,resonance:state.resonance,hall:state.hallBattles});})()`);
check('Scene Memories only lists seen scenes for recruits present in this run', `(() => {state.gameMode='hallBattles'; state.party=['Verseborn','Mira']; saveRecruitSceneHistory({seen:['mira-welcome','seerin-welcome'],lastByRecruit:{Mira:'mira-welcome',Seerin:'seerin-welcome'}}); const html=sceneMemoriesHtml(); return html.includes('data-replay-scene="mira-welcome"')&&!html.includes('data-replay-scene="seerin-welcome"')&&!html.includes('mira-humorous');})()`);
check('Existing Hall saves expose missed first-arrival scenes without autoplaying them', `(() => {localStorage.removeItem(HALL_SCENE_HISTORY_KEY); state.gameMode='hallBattles'; state.party=['Verseborn',...HALL_RECRUITS]; const html=sceneMemoriesHtml(); return html.includes('Unseen Arrivals')&&(html.match(/data-play-arrival-scene=/g)||[]).length===HALL_RECRUITS.length+1&&mode!=='talk';})()`);
check('Playing a missed arrival moves it into Scene Memories', `(() => {localStorage.removeItem(HALL_SCENE_HISTORY_KEY); state.gameMode='hallBattles'; state.party=['Verseborn','Mira']; state.activeParty=['Verseborn','Mira']; const started=playUnseenArrival('mira-welcome'); skipTalk(); const html=sceneMemoriesHtml(); return started&&html.includes('data-replay-scene="mira-welcome"')&&!html.includes('data-play-arrival-scene="mira-welcome"');})()`);
check('A fresh Hall starts its intro once while Continue Hall does not retrigger it', `(() => {const oldHall=localStorage.getItem(HALL_SAVE_KEY),oldScenes=localStorage.getItem(HALL_SCENE_HISTORY_KEY),oldAssets=runtimeAssetsReady; try {runtimeAssetsReady=true;localStorage.removeItem(HALL_SAVE_KEY);localStorage.removeItem(HALL_SCENE_HISTORY_KEY);startHallBattles(false);const fresh=mode==='talk'&&activeRecruitScene?.id===EMBER_HALL_INTRO_ID&&loadRecruitSceneHistory().seen.includes(EMBER_HALL_INTRO_ID);skipTalk();saveGame(HALL_SAVE_KEY);startHallBattles(true);return fresh&&mode==='walk'&&!activeRecruitScene&&loadRecruitSceneHistory().seen.includes(EMBER_HALL_INTRO_ID);} finally {runtimeAssetsReady=oldAssets;activeRecruitScene=null;mode='walk';[[HALL_SAVE_KEY,oldHall],[HALL_SCENE_HISTORY_KEY,oldScenes]].forEach(([key,value])=>value===null?localStorage.removeItem(key):localStorage.setItem(key,value));}})()`);
check('The Hall introduction has one memory entry and can replay without changing progress', `(() => {const oldScenes=localStorage.getItem(HALL_SCENE_HISTORY_KEY); try {state.gameMode='hallBattles';state.party=['Verseborn'];state.activeParty=['Verseborn'];state.gold=222;state.hallBattles={unlockedStage:7,clearedStages:[1,2],recruitStages:[],pendingRecruit:0};saveRecruitSceneHistory({seen:[EMBER_HALL_INTRO_ID],lastByRecruit:{Verseborn:EMBER_HALL_INTRO_ID}});const html=sceneMemoriesHtml(),before=JSON.stringify({gold:state.gold,hall:state.hallBattles}),started=replayRecruitScene(EMBER_HALL_INTRO_ID);skipTalk();return (html.match(/data-replay-scene="ember-hall-welcome"/g)||[]).length===1&&started&&before===JSON.stringify({gold:state.gold,hall:state.hallBattles});} finally {activeRecruitScene=null;mode='walk';oldScenes===null?localStorage.removeItem(HALL_SCENE_HISTORY_KEY):localStorage.setItem(HALL_SCENE_HISTORY_KEY,oldScenes);}})()`);
check('Welcome scene actors stay roster-aware except for the Hall introduction guides', `(() => {state.party=['Verseborn','Kael'];const kael=RECRUIT_SCENES.find(scene=>scene.id==='kael-welcome'),kaelActors=recruitSceneActors(kael,recruitScenePartner(kael)),kaelLines=kael.build({partner:'Verseborn',history:{seen:[],lastByRecruit:{}},actors:kaelActors.map(actor=>actor.id)}),intro=RECRUIT_SCENES.find(scene=>scene.id===EMBER_HALL_INTRO_ID),introActors=recruitSceneActors(intro,null);return kaelActors.map(actor=>actor.id).join(',')==='Verseborn,Kael'&&!kaelLines.some(line=>line[0]==='Glimmer')&&introActors.map(actor=>actor.id).join(',')==='Verseborn,Marla,Glimmer';})()`);
check('Recruit scene casts are staged in the middle of the screen', `(() => {state.party=['Verseborn',...HALL_RECRUITS];return RECRUIT_SCENES.every(scene=>recruitSceneActors(scene,recruitScenePartner(scene)).every(actor=>actor.baseline>=128&&actor.baseline<=140));})()`);
check('Recruit scene speakers and staged cast have existing dialogue portraits', `RECRUIT_SCENES.every(scene=>portraitSources[scene.recruit]&&scene.preferred.every(id=>portraitSources[id])&&(scene.cast||[]).every(id=>portraitSources[id]))`);
check('Mira and Verseborn gain two-turn single-target Silence skills', `(() => {const mira=baseJobs.Mira.skills.find(skillEntry=>skillEntry.name==='Cut the Tongue'),verseborn=baseJobs.Verseborn.skills.find(skillEntry=>skillEntry.name==='Hushed Refrain');return STATUS_DEFS.silence.duration===2&&mira?.anim==='melee'&&mira.power>=20&&mira.status?.type==='silence'&&mira.status.duration===2&&verseborn?.element==='Sound'&&verseborn.power>0&&verseborn.status?.type==='silence'&&verseborn.status.duration===2;})()`);
check('Cut the Tongue applies Silence and two-turn Shadow Exposed', `(() => {const source=battleUnit('Mira'),target={name:'Exposure Test',hp:100,max:100,statuses:[],weak:'Fire'},sk=baseJobs.Mira.skills.find(entry=>entry.name==='Cut the Tongue');battle={party:[source],enemies:[target],round:1,turnIndex:0,turnQueue:[{side:'party',id:'Mira'}],usedOnce:{},extraTurns:0,resolving:false};applySkillStatuses(source,target,sk);return statusOf(target,'silence')?.remaining===2&&statusOf(target,'shadowExposed')?.remaining===2&&skillHitsElementWeakness(target,sk);})()`);
check('Voidthorn Mark gets its larger Shadow Exposed payoff', `(() => {const sk=baseJobs.Mira.skills.find(entry=>entry.name==='Voidthorn Mark'),target={hp:100,max:100,statuses:[{type:'shadowExposed',remaining:2}],weak:'Fire'};return sk.shadowExposureBonus===.6&&Math.abs(skillWeaknessMultiplier('Mira',sk,target)-1.55*1.6*(1+effectValue('Mira','weaknessDamage')))<.000001;})()`);
check('Silent Step doubles Mira Stun chance for its own turn and the next', `(() => {const source=battleUnit('Mira'),sk=baseJobs.Mira.skills.find(entry=>entry.name==='Silent Step'),base=effectValue('Mira','statusOnHit','stun');source.statuses=[];const current=skillStatusOnHitChance(source,sk,'stun');applyStatus(source,'stunFocus',source,{duration:1,force:true});const next=skillStatusOnHitChance(source,{name:'Attack'},'stun');return sk.doublesStunChance&&current===Math.min(.95,base*2)&&next===Math.min(.95,base*2)&&statusOf(source,'stunFocus').remaining===1;})()`);
check('Every damaging Mira skill adds half AGI to its primary offense stat', `(() => {const stats=totals('Mira'),unit={id:'Mira',statuses:[]};return battleSkills('Mira',unit).filter(skillTargetsEnemies).every(sk=>skillOffensiveStat('Mira',sk,unit,stats)===Math.round(stats[skillScaling(sk)]+stats.agi*.5))&&skillFormula(baseJobs.Mira.skills.find(sk=>sk.name==='Voidthorn Mark'),'Mira').includes('MAG + 0.5 AGI');})()`);
check('Silenced enemies are restricted to their basic physical action', `chooseEnemyAction.toString().includes('statusOf(unit, "silence")')&&chooseEnemyAction.toString().includes('enemyActionForKind(unit, "melee")')`);
check('Torren grants party Vampiric and Sparky grants a stronger single-ally version', `(() => {const stew=baseJobs.Torren.skills.find(skillEntry=>skillEntry.name==='Hearty Red Stew'),ember=baseJobs.Sparky.skills.find(skillEntry=>skillEntry.name==='Emberblood');return STATUS_DEFS.vampiric.duration===3&&stew?.targetSide==='party'&&stew.partyWide&&stew.buffs?.[0]?.type==='vampiric'&&stew.buffs[0].value===.2&&stew.buffs[0].duration===3&&ember?.targetSide==='ally'&&ember.buffs?.[0]?.type==='vampiric'&&ember.buffs[0].value===.25&&ember.buffs[0].duration===3;})()`);
check('Vampiric recovery uses direct damage and the active buff percentage', `useSkill.toString().includes('directDamageDealt += dmg')&&useSkill.toString().includes('statusValue(u, "vampiric")')&&useSkill.toString().includes('directDamageDealt * vampiric')`);
check('Single-ally support skills use the existing living-ally target picker', `chooseSkillTarget.toString().includes('sk.targetSide === "ally"')&&renderBattleTargets.toString().includes('battle.party.filter(ally => ally.hp > 0)')&&useSkill.toString().includes('sk.targetSide === "ally"')`);
check('Gear search indexes names, rarity, effects, statuses and rolled affixes', `(() => {const source=gearSearchText.toString();return ['gearDisplayName','gearRarity','gearEffects','entry.status','entry.element','formatAffix'].every(token=>source.includes(token));})()`);
check('Gear filtering combines search, slot, rarity, usability, equipment and affix matching', `(() => {const source=filteredSortedGear.toString();return ['gearSearchText','gearBrowser.slot','gearBrowser.rarity','canEquip','gearBrowser.equipped','gearBrowser.affixes','matches.every','matches.some'].every(token=>source.includes(token));})()`);
check('Gear sorting exposes requested stats plus numerical selected-affix strength', `GEAR_SORT_FIELDS.map(entry=>entry[0]).join(',')==='newest,name,itemPower,rarity,affixCount,str,agi,mag,def,hp,mp,crit,speed'&&gearAffixFacet({type:'statPct',stat:'mag'}).key==='statPct:mag'&&gearAffixFacet({type:'statusOnHit',status:'stun'}).key==='status:stun'&&gearAffixFacetValue.toString().includes('Math.max(...values)')&&gearBrowserToolbarHtml.toString().includes('selectedAffixSorts.map')`);
check('Gear controls separate fixed stats from affixes and reset both', `gearBrowserToolbarHtml.toString().includes('placeholder="Search gear..."')&&gearBrowserToolbarHtml.toString().includes('data-gear-stat="')&&gearBrowserToolbarHtml.toString().includes('data-gear-match="any"')&&gearBrowserToolbarHtml.toString().includes('data-gear-match="all"')&&bindGearBrowserControls.toString().includes('search.oninput')&&resetGearBrowser.toString().includes('stats: []')&&resetGearBrowser.toString().includes('affixes: []')`);
check('Fixed MAG filtering includes non-weapons and excludes MAG-affix-only gear', `(() => {const oldAffixes=structuredClone(state.gearAffixes),oldBrowser=structuredClone(gearBrowser);try {state.gearAffixes['Flameguard Plate']=[{label:"Scholar's",type:'statPct',stat:'mag',value:.15}];Object.assign(gearBrowser,{search:'',stats:['mag'],statMatch:'any',affixes:[],affixMatch:'any',slot:'all',rarity:'all',usability:'all',equipped:'all',sort:'mag',direction:'desc'});const entries=['Cinder Star','Workshop Coat','Flameguard Plate','Voice of Verse'].map(ref=>({ref,gear:gearByName(ref)}));return filteredSortedGear(entries).map(entry=>entry.ref).join(',')==='Voice of Verse,Cinder Star,Workshop Coat';}finally {state.gearAffixes=oldAffixes;Object.assign(gearBrowser,oldBrowser);}})()`);
check('Selecting a fixed stat sorts that stat highest first instead of newest', `gearSortForStat('mag')==='mag'&&gearSortForStat('stam')==='def'&&bindGearBrowserControls.toString().includes('gearBrowser.sort = gearSortForStat')`);
check('Combined gear filters sort actual stored Stun rolls from strongest to weakest', `(() => {const oldAffixes=structuredClone(state.gearAffixes),oldRarities={...state.gearRarities},oldBrowser=structuredClone(gearBrowser);try {state.gearAffixes['Guildsteel Saber']=[{label:'Fleet',type:'statPct',stat:'agi',value:.1},{label:'Stormbreaking',type:'statusOnHit',status:'stun',value:.05}];state.gearAffixes['Ember Pike']=[{label:'Fleet',type:'statPct',stat:'agi',value:.12},{label:'Stormbreaking',type:'statusOnHit',status:'stun',value:.08}];state.gearAffixes['Shelter Staff']=[{label:'Fleet',type:'statPct',stat:'agi',value:.14},{label:'Stormbreaking',type:'statusOnHit',status:'stun',value:.06}];state.gearRarities['Guildsteel Saber']='Epic';state.gearRarities['Ember Pike']='Epic';state.gearRarities['Shelter Staff']='Rare';Object.assign(gearBrowser,{search:'stun',stats:[],affixes:['statPct:agi'],affixMatch:'all',slot:'weapon',rarity:'Epic',usability:'all',equipped:'all',sort:'affix:status:stun',direction:'desc'});const entries=['Guildsteel Saber','Ember Pike','Shelter Staff'].map(ref=>({ref,gear:gearByName(ref)}));return filteredSortedGear(entries).map(entry=>entry.ref).join(',')==='Ember Pike,Guildsteel Saber';}finally {state.gearAffixes=oldAffixes;state.gearRarities=oldRarities;Object.assign(gearBrowser,oldBrowser);}})()`);
