check('Gear menu exposes per-hero and whole-roster optimization with both source modes', `(() => {const html=autoEquipToolbarHtml('Mira');return html.includes('data-auto-equip="hero"')&&html.includes('Optimize Mira')&&html.includes('data-auto-equip="party"')&&html.includes('Optimize everybody')&&html.includes('All gear')&&html.includes('Unequipped gear');})()`);
check('Whole-roster auto equip respects usability and owned copy limits', `(() => {const oldParty=[...state.party],oldGear=Object.fromEntries(Object.entries(baseJobs).map(([id,hero])=>[id,{...hero.gear}]));try {state.party=Object.keys(baseJobs);autoEquipParty('all');const refs=state.party.flatMap(id=>Object.values(baseJobs[id].gear).filter(Boolean));const valid=state.party.every(id=>Object.values(baseJobs[id].gear).every(ref=>!ref||canEquip(id,gearByName(ref))));const counts=refs.reduce((map,ref)=>(map[ref]=(map[ref]||0)+1,map),{});return valid&&Object.entries(counts).every(([ref,count])=>count<=gearCopyCount(ref));}finally {state.party=oldParty;Object.entries(oldGear).forEach(([id,gear])=>baseJobs[id].gear=gear);}})()`);
check('Unequipped-only optimization keeps gear worn by other heroes unavailable', `autoEquipHero.toString().includes('!token.equippedBy || token.equippedBy === id')&&autoEquipParty.toString().includes('choice.equippedBy !== id')`);
check('Zero HP plays DOWN once and only revive recovery clears it', `(() => {const unit={name:'Test Hero',hp:0,max:100,anim:'idle',guarding:true};const fell=markBattleUnitDown(unit);const deathStarted=Number.isFinite(unit.deathTick);const firstDeathTick=unit.deathTick;const repeated=!markBattleUnitDown(unit)&&unit.deathTick===firstDeathTick;const stayedDown=unit.down&&unit.hp===0&&unit.anim==='death'&&!unit.guarding;const restored=reviveBattleUnit(unit,.35);return fell&&deathStarted&&repeated&&stayedDown&&restored===35&&!unit.down&&unit.anim==='idle'&&unit.deathTick===null;})()`);
